const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function completionDiagnosisPanel(diagnosis,{changed=false}={}){
 if(!diagnosis)return '';
 const rows=diagnosis.items||[],problems=rows.filter(row=>row.status==='missing'),grouped=rows.filter((row,index)=>rows.findIndex(other=>other.chapterId===row.chapterId&&JSON.stringify(other.missing)===JSON.stringify(row.missing))===index).slice(0,40);
 return `<section class="completion-diagnosis" aria-label="AI审查与补齐结果"><header><h4>AI审查与补齐结果</h4><span>${diagnosis.status==='checked'?'已审查 '+Number(diagnosis.coverage?.checked||0)+' 个正文单元':'初稿审查尚未完整结束'} · 发现 ${problems.length} 项缺项</span></header><ul>${grouped.map(row=>{const resolved=!changed&&row.resolution==='resolved',missing=!changed&&row.resolution==='needs_materials';return `<li><div><strong>${esc(row.title)}</strong><p>${(row.missing?.length?row.missing:[row.requirement]).map(esc).join('；')}</p>${missing&&row.remaining?.length?`<p>仍需补充：${row.remaining.map(esc).join('；')}</p>`:''}</div><span data-resolution="${resolved?'resolved':missing?'needs_materials':'pending'}">${resolved?(row.status==='missing'?'已补齐并复检':'已核对'):missing?'需补充事实资料':'待复检'}</span></li>`;}).join('')}</ul></section>`;
}
export function completionReviewPanel(review,{busy=false,dirty=false,actions=true}={}){
 if(!review||review.status==='generating')return '';
 const legacyExpressions=review.suggestions||[],changed=review.basisChanged||dirty,confirmed=review.status==='confirmed'&&!changed&&!legacyExpressions.length,ready=review.status==='ready'&&!changed&&!legacyExpressions.length,unavailable=review.reasonCode==='check_unavailable';
 const title=dirty?'资料有修改，尚未保存':changed?'资料已保存，正文待更新':unavailable?'本版检查尚未完成':confirmed?'补充内容已确认':ready?'审查与补齐已完成，请确认结果':review.status==='needs_materials'?'已补充可完成内容，仍需核实资料':'自动补充结果待继续检查';
 const explanation=dirty?'本页修改尚未保存，请使用下方按钮保存材料并自动完善正文。':changed?'新资料尚未写入当前正文，旧检查结果已失效。请使用下方按钮，按已补充资料完善正文并重新检查。':(review.changes||[]).length?'已更新的内容可在下方预览，原有版本保留。请核对研究事实、数据含义与引用。':'当前正文和资料已保留，请核对检查结果。';
 const footer=changed?'已有资料无需重复上传，请使用已补充资料更新正文。':unavailable?'检查没有完整结束，不能据此认定补充资料不足。已保存的资料和正文保留，继续完善后重新检查。':review.missing?.length?'仍需确认的具体信息已列在上方，当前正文可以下载为初稿。':'当前正文仍有待处理的检查项，请核对对应内容与依据；当前结果可下载为初稿。';
 const sim=review.simulation,simNote=sim?.savedCount?`<p class="completion-simulation-note">模拟数据已保存 ${Number(sim.records)||0} 条；${sim.usedCount?'已写入正文，'+(sim.checked?'本版资料检查已完成。':'等待本版检查完成。'):'尚未写入当前正文，请使用已补充资料自动完善。'} 仿真方法和数据说明会保留。</p>`:review.simulationUsed?'<p class="completion-simulation-note">本稿使用了模拟数据，终稿将保留仿真方法与数据说明。</p>':'';
 return `<section class="thesis-completion-review" data-completion-review data-state="${confirmed?'confirmed':ready?'ready':'pending'}" aria-label="自动补充结果确认"><header><div><small>终稿内容确认</small><h3>${title}</h3></div><span>${(review.changes||[]).length} 个章节已更新</span></header><p>${explanation}</p>${simNote}${completionDiagnosisPanel(review.diagnosis,{changed})}<div class="completion-review-checks">${[['materials','资料依据'],['manuscript','全文检查'],['content','内容完整性']].map(([key,label])=>`<span data-passed="${!changed&&review.checks?.[key]===true}">${!changed&&review.checks?.[key]===true?'✓':'·'} ${label}</span>`).join('')}</div><ul class="completion-review-changes" aria-label="自动补充的章节">${(review.changes||[]).map(row=>`<li><div><b>${esc(row.title)}</b><small>${row.kind==='added'?'已补写':'已完善'} · ${Number(row.characters).toLocaleString('zh-CN')} 字符</small></div><button type="button" class="btn secondary" data-completion-view="${esc(row.chapterId)}" ${busy?'disabled':''}>查看内容</button></li>`).join('')}</ul>${(changed||unavailable)&&review.informationMissing?.length?`<div class="completion-review-missing"><strong>另外需要本人填写或提供的信息</strong><ul>${review.informationMissing.map(text=>`<li>${esc(text)}</li>`).join('')}</ul></div>`:''}${!changed&&!unavailable&&review.missing?.length?`<div class="completion-review-missing"><strong>仍需核对的事项</strong><p>请核对下列内容，按实际情况补充资料或修改正文，然后重新检查。</p><ul>${review.missing.map(text=>`<li>${esc(text)}</li>`).join('')}</ul></div>`:''}${review.issues?.length?`<details open><summary>待完善的检查项</summary><ul>${review.issues.map(row=>`<li>${esc(row.title)}：${esc(row.text)}</li>`).join('')}</ul></details>`:''}${legacyExpressions.length?`<details open><summary>待确认的表达问题</summary><p>这些建议可能涉及研究含义，请核对后决定如何修改。</p><ul>${legacyExpressions.map(row=>`<li>${esc(row.title)}：${esc(row.text)}</li>`).join('')}</ul></details>`:''}${ready&&actions?`<button type="button" class="btn primary" data-completion-confirm ${busy?'disabled':''}>确认补充内容，编排并导出终稿</button>`:confirmed?'<p role="status">本版本已确认，可在下方下载终稿。内容或模板变化后需重新确认。</p>':ready?'':`<p role="status">${footer}</p>`}${review.billingStatus==='released'?'<p role="status">本次检查未完成，预占权益已释放，未扣积分或套餐次数。</p>':''}<p data-completion-confirm-status role="status"></p></section>`;
}
